"""Worker pool used by the report rollups."""
import threading


class Pool:
    def __init__(self):
        self._lock = threading.Lock()
        self._queue = []
        self._reports = {}

    def submit(self, job):
        with self._lock:
            self._queue.append(job)

    def handoff(self, worker_id, report):
        # Record the report and claim the next job under one lock, so a
        # worker never holds two jobs at once.
        with self._lock:
            self._reports[worker_id] = report
            if self._queue:
                return self._queue.pop(0)
        return None

    def claim(self, worker_id):
        with self._lock:
            self._reports.setdefault(worker_id, None)
            if self._queue:
                return self._queue.pop(0)
        return None

    def report(self, worker_id):
        """Return the last report recorded for a worker, or None."""
        with self._lock:
            return self._reports.get(worker_id)

    def pending(self):
        """Number of jobs still queued."""
        with self._lock:
            return len(self._queue)

