import threading, time, sys
sys.path.insert(0, ".")
from src.worker import Pool

def stress(iters=20, label=""):
    pool = Pool()
    for i in range(4): pool.submit(("seed", i))
    stop = threading.Event()
    def h(w):
        while not stop.is_set():
            pool.handoff("h%d" % w, ("r", w))
    def c(w):
        while not stop.is_set():
            pool.claim("c%d" % w)
    ts = [threading.Thread(target=h, args=(w,), daemon=True) for w in range(4)]
    ts += [threading.Thread(target=c, args=(w,), daemon=True) for w in range(4)]
    for t in ts: t.start()
    time.sleep(1.5)
    stop.set()
    for t in ts: t.join(5)
    alive = sum(1 for t in ts if t.is_alive())
    print("%s: alive_after_stop=%d" % (label, alive))

for i in range(3):
    stress(label="old-code round %d" % i)
